 "content": "def transform(grid):
    """Extend the center row and column of each solid 3x3 block."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find solid 3x3 blocks as monochrome connected components.
    seen = set()
    blocks = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            if (len(cells) == 9 and max(ys)-min(ys) == 2 and
                    max(xs)-min(xs) == 2):
                blocks.append((min(ys), min(xs), color))

    rays = {}
    for top, left, color in blocks:
        cr, cc = top + 1, left + 1
        for x in range(w):
            if x < left or x >= left + 3:
                rays.setdefault((cr, x), set()).add(color)
        for y in range(h):
            if y < top or y >= top + 3:
                rays.setdefault((y, cc), set()).add(color)
    for (r, c), colors in rays.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
